// Sentinel (KQL): monthly MTTD and MTTR in minutes from closed incidents
SecurityIncident
| where Status == "Closed" and TimeGenerated > ago(180d)
| extend FirstEvent = todatetime(AdditionalData.firstActivityTime)
| extend Detect = datetime_diff('minute', CreatedTime, FirstEvent)
| extend Respond = datetime_diff('minute', ClosedTime, CreatedTime)
| summarize Incidents = count(),
            MTTD_min = round(avg(Detect)), MedianTTD = percentile(Detect, 50),
            MTTR_min = round(avg(Respond)), MedianTTR = percentile(Respond, 50)
  by Month = startofmonth(CreatedTime)
| order by Month asc
// Month        Incidents  MTTD_min  MedianTTD  MTTR_min  MedianTTR
// 2026-08-01          31       412        150       188        95
// 2026-09-01          28       301        120       171        88
// 2026-10-01          33       204         75       142        70

